import { useEffect } from 'react';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { websocketTransport } from '06_shared/lib/websocket';
import { WSEventEnum } from '06_shared/types/types';
import { symbolActions } from '../slice/symbolSlice';
// Чистий push-потік без GET-запиту, тож підписується сама сутність.
// Виклик живе в компоненті, який показує ціну, — тож їде в його
// лінивому чанку, а не в загальному.
const useSubscribeSymbolPrice = () => {
    const dispatch = useAppDispatch();
    useEffect(() => {
        return websocketTransport.on(WSEventEnum.SYMBOL_PRICE_BASE_FROM_CORE, (message) => {
            const payload = message;
            dispatch(symbolActions.addSymbolPrice({
                ...payload.symbol_price_base,
                trend_moment: payload.trend_moment,
            }));
        });
    }, [dispatch]);
};
export { useSubscribeSymbolPrice };
