import { createSlice } from '@reduxjs/toolkit';
const initialState = {
    symbol_price_list: [],
    symbol_price_current: undefined,
};
export const symbolSlice = createSlice({
    name: 'symbol',
    initialState,
    reducers: {
        addSymbolPrice: (state, action) => {
            state.symbol_price_list.push(action.payload);
            state.symbol_price_current = action.payload;
        },
        removeFirstItemFromSymbolPriceList: (state) => {
            state.symbol_price_list.shift();
        },
        // Скидання при виході. Цей слайс єдиний із публічних, чий стан
        // реально переживав вихід і був видимий користувачеві.
        resetSymbolSlice() {
            return initialState;
        },
    }
});
export const { actions: symbolActions } = symbolSlice;
export const { reducer: symbolReducer } = symbolSlice;
